63: function normalizeRatios(input: RatioState): RatioState {
64:   const compactAtRatio = clamp(input.compactAtRatio, 10, 98);
65:   return {
66:     microcompactFloorRatio: Math.min(clamp(input.microcompactFloorRatio, 10, 95), compactAtRatio),
67:     compactAtRatio,
68:     summarizeAtRatio: Math.max(clamp(input.summarizeAtRatio, 10, 99), compactAtRatio),
69:   };
