228: /**
229:  * Reconcile user-supplied compaction ratios into a safe ordering.
230:  *
231:  * The three tiers must satisfy `floor < compact < summarize` or the manager
232:  * fires them in the wrong order (e.g. an emergency window-compact before the
233:  * cheaper summary). Users edit these freely in settings.json, so we clamp
234:  * rather than trust: summarize is pulled up to at least compact, floor is
235:  * pushed down to at most compact. Absent fields are left undefined so the
236:  * ContextManager keeps its own default for them.
237:  */
238: export function clampContextRatios(input: {
239:   compactAtRatio?: number;
240:   summarizeAtRatio?: number;
241:   microcompactFloorRatio?: number;
242: }): {
243:   compactAtRatio?: number;
244:   summarizeAtRatio?: number;
245:   microcompactFloorRatio?: number;
246: } {
247:   const compact = input.compactAtRatio;
248:   const summarize =
249:     input.summarizeAtRatio !== undefined && compact !== undefined
250:       ? Math.max(input.summarizeAtRatio, compact)
251:       : input.summarizeAtRatio;
252:   const floor =
253:     input.microcompactFloorRatio !== undefined && compact !== undefined
254:       ? Math.min(input.microcompactFloorRatio, compact)
255:       : input.microcompactFloorRatio;
256:   return {
257:     compactAtRatio: compact,
258:     summarizeAtRatio: summarize,
259:     microcompactFloorRatio: floor,
260:   };
261: }
