171:  * Merge `b` into `a`, where a null in the patch means "delete this key".
172:  *
173:  * The delete must hold no matter what shape `a` had. It used to apply only when
174:  * the target already held an object at that key — otherwise the branch below
175:  * assigned the patch object verbatim, nulls included. A persisted null then
176:  * failed schema validation for the WHOLE settings file, and every reader that
177:  * fails closed on a parse error (e.g. panelAppPolicy) silently behaved as if the
178:  * project had configured nothing. `stripNulls` keeps the contract shape-agnostic
179:  * so no caller has to know whether a key already exists on disk.
180:  */
181: function deepMerge(
182:   a: Record<string, unknown>,
183:   b: Record<string, unknown>,
184: ): Record<string, unknown> {
185:   const out: Record<string, unknown> = { ...a };
186:   for (const [k, v] of Object.entries(b)) {
187:     if (v === null) {
188:       delete out[k];
189:     } else if (
190:       v &&
191:       typeof v === "object" &&
192:       !Array.isArray(v) &&
193:       typeof out[k] === "object" &&
194:       out[k] !== null &&
195:       !Array.isArray(out[k])
196:     ) {
197:       out[k] = deepMerge(out[k] as Record<string, unknown>, v as Record<string, unknown>);
198:     } else {
199:       out[k] = stripNulls(v);
200:     }
201:   }
202:   return out;
203: }
204: 
205: /** Drop null-valued keys from a plain object recursively; other values pass through. */
206: function stripNulls(value: unknown): unknown {
207:   if (!value || typeof value !== "object" || Array.isArray(value)) return value;
208:   const out: Record<string, unknown> = {};
209:   for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
210:     if (FORBIDDEN_SETTING_KEYS.has(k)) continue;
211:     if (v === null) continue;
212:     out[k] = stripNulls(v);
213:   }
214:   return out;
215: }

